def run_projection_server() -> None:
    sys.argv = ["single_task_public_demo.py", "--host", "127.0.0.1", "--port", str(INTERNAL_PORT)]
    import single_task_public_demo
    single_task_public_demo.main()


def wait_for_projection_server() -> None:
    deadline = time.monotonic() + 120
    while time.monotonic() < deadline:
        try:
            with urllib.request.urlopen(INTERNAL_ORIGIN + "/readyz", timeout=2) as response:
                if response.status == 200:
                    return
        except (OSError, urllib.error.URLError):
            time.sleep(0.5)
    raise RuntimeError("Projection renderer did not become ready in time")


def proxy_response(upstream: httpx.Response) -> Response:
    headers = {name: upstream.headers[name] for name in ("content-type", "cache-control", "set-cookie") if name in upstream.headers}
    return Response(content=upstream.content, status_code=upstream.status_code, headers=headers)


