def page(title: str, body: str, active: str = "") -> str:
    links = [("Play", "/play", "play", "任务体验", "Play"), ("Leaderboard", "/leaderboard", "leaderboard", "排行榜", "Leaderboard"), ("Paper", "/paper", "paper", "论文", "Paper"), ("Method", "/about", "about", "方法", "Method")]
    nav_parts = []
    for _label, href, key, zh, en in links:
        class_name = "active" if key == active else ""
        nav_parts.append(f'<a class="{class_name}" href="{href}">{bilingual(zh, en)}</a>')
    nav = "".join(nav_parts)
    body_class = "paper-mac" if active == "paper" else ""
    title_pair = {"Home": ("首页", "Home"), "Play": ("任务体验", "Play"), "Leaderboard": ("排行榜", "Leaderboard"), "Paper": ("论文", "Paper"), "Method": ("方法", "Method"), "About": ("方法", "Method")}.get(title, (title, title))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080C14"><title>{title_pair[0]} · {title_pair[1]} - RoTA-Bench</title><style>{STYLE}.lang-toggle{{background:#101A28;color:#55D6E8;border:1px solid #2A3B50;padding:7px 11px;font:inherit;cursor:pointer}}.nav-inner{{gap:18px}}.nav-links{{margin-left:auto}}[data-language="en"]{{display:none}}.language-en [data-language="zh"]{{display:none}}.language-en [data-language="en"]{{display:initial}}</style></head><body class="{body_class}"><header class="nav"><div class="nav-inner"><a class="brand" href="/">{bilingual("RoTA-Bench", "RoTA-Bench")}</a><nav class="nav-links">{nav}</nav><button class="lang-toggle" id="language-toggle" type="button" aria-label="Switch language">中文</button></div></header>{body}<script>const langButton=document.getElementById('language-toggle');let siteLang=localStorage.getItem('rota-language')||'en';function applySiteLanguage(){{document.body.classList.toggle('language-en',siteLang==='en');document.documentElement.lang=siteLang==='zh'?'zh-CN':'en';langButton.textContent=siteLang==='zh'?'EN':'中文';langButton.setAttribute('aria-label',siteLang==='zh'?'Switch language':'切换中英文');}}langButton.addEventListener('click',()=>{{siteLang=siteLang==='zh'?'en':'zh';localStorage.setItem('rota-language',siteLang);applySiteLanguage();}});applySiteLanguage();</script></body></html>'''


