def paper_html() -> str:
    from paper_view import render

    return page("Paper", render(), "paper")


def about_html() -> str:
    from paper_source import render_excerpt
    from method_appendix import render as render_method_appendix

    source_intro = bilingual(render_excerpt("introduction", "zh"), render_excerpt("introduction", "en"))
    source_motivation = bilingual(render_excerpt("motivation", "zh"), render_excerpt("motivation", "en"))
    source_task = bilingual(render_excerpt("task", "zh"), render_excerpt("task", "en"))
    source_construction = bilingual(render_excerpt("construction", "zh"), render_excerpt("construction", "en"))
    pose_error_equation = """<math display="block" class="equation" aria-label="Pose error is the minimum rotation distance to an equivalent target pose"><msub><mi>e</mi><mi>t</mi></msub><mo>=</mo><munder><mi>min</mi><mrow><mi>S</mi><mo>∈</mo><mi>𝒢</mi></mrow></munder><msub><mi>d</mi><mrow><mi>SO</mi><mo>(</mo><mn>3</mn><mo>)</mo></mrow></msub><mo>(</mo><msub><mi>R</mi><mi>t</mi></msub><mo>,</mo><msup><mi>R</mi><mo>★</mo></msup><mi>S</mi><mo>)</mo><mo>=</mo><munder><mi>min</mi><mrow><mi>S</mi><mo>∈</mo><mi>𝒢</mi></mrow></munder><mi>arccos</mi><mo>(</mo><mfrac><mrow><mi>Tr</mi><mo>(</mo><msub><mi>R</mi><mi>t</mi></msub><msup><mrow><mo>(</mo><msup><mi>R</mi><mo>★</mo></msup><mi>S</mi><mo>)</mo></mrow><mi>⊤</mi></msup><mo>)</mo><mo>−</mo><mn>1</mn></mrow><mn>2</mn></mfrac><mo>)</mo><mo>.</mo></math>"""
    source_metrics = f'''<div class="metric-copy"><h4 data-language="en">Task performance metrics</h4><h4 data-language="zh">任务表现指标</h4><p data-language="en">Task Success Rate is the fraction of episodes reaching IoU s<sub>t</sub> ≥ 0.90. Mean Final IoU and mean rotation steps average the final IoU and executed rotations over all tasks, including failures. An episode fails if it ends through STOP, the 48-decision limit, or stagnation before reaching the threshold.</p><p data-language="zh">任务成功率是达到 IoU s<sub>t</sub> ≥ 0.90 的回合占比。平均最终 IoU 和平均旋转步数分别对所有任务（包括失败任务）的最终 IoU 和实际旋转次数取平均。若回合在达到阈值前因 STOP、用尽 48 次决策或停滞而结束，则该回合判为失败。</p><h4 data-language="en">Geometric diagnostic metrics</h4><h4 data-language="zh">几何诊断指标</h4><p data-language="en">We compute 3D pose error from ground-truth pose data, which are not provided to the model:</p><p data-language="zh">我们根据真实姿态数据计算三维姿态误差，但这些数据不会提供给模型：</p>{pose_error_equation}<p data-language="en">Here, 𝒢 contains the object's estimated symmetries. Pose error is the smallest rotation needed to reach an equivalent target pose. Equivalent target poses produce exact alignment, whereas task success requires only a projection IoU of at least 0.90. Thus, a successful pose need not have zero pose error. Pose error is used as a geometric diagnostic rather than as the task objective; a lower pose error does not necessarily imply a larger immediate IoU improvement. Surface coverage is the fraction of the object's surface observed during an episode.</p><p data-language="zh">其中，𝒢 表示估计得到的物体对称变换集合。姿态误差指到达任一等价目标姿态所需的最小旋转角。等价目标姿态会产生精确对齐，而任务成功只要求投影 IoU 至少达到 0.90。因此，成功姿态的姿态误差不一定为零。姿态误差用于几何诊断，而非任务目标；姿态误差较小并不必然意味着当前 IoU 会有更大的提升。表面覆盖率指一个回合中被观察到的物体表面比例。</p><p data-language="en">A direction (axis and sign) is effective if at least one legal angle reduces pose error: <math class="inline-equation"><munder><mi>min</mi><mi>θ</mi></munder><mi>e</mi><mo>(</mo><msub><mi>R</mi><mi>t</mi></msub><mo>,</mo><mi>d</mi><mo>,</mo><mi>θ</mi><mo>)</mo><mo>&lt;</mo><msub><mi>e</mi><mi>t</mi></msub></math>. Effective Direction Rate is the fraction of rotations that choose such a direction; the chosen angle may still increase error. For effective directions, let <math class="inline-equation"><msup><mi>Θ</mi><mo>★</mo></msup><mo>=</mo><mi>argmin</mi><mi>e</mi><mo>(</mo><msub><mi>R</mi><mi>t</mi></msub><mo>,</mo><mi>d</mi><mo>,</mo><mi>θ</mi><mo>)</mo></math> be the best legal angles. Best Legal Angle Rate is the fraction choosing one of these angles. Angle Gap measures the distance from the selected angle to a best legal angle. Angle Loss is the extra pose error caused by the chosen angle.</p><p data-language="zh">若某个方向（旋转轴及正负方向）下至少存在一个合法角度可以降低姿态误差，即 <math class="inline-equation"><munder><mi>min</mi><mi>θ</mi></munder><mi>e</mi><mo>(</mo><msub><mi>R</mi><mi>t</mi></msub><mo>,</mo><mi>d</mi><mo>,</mo><mi>θ</mi><mo>)</mo><mo>&lt;</mo><msub><mi>e</mi><mi>t</mi></msub></math>，则该方向为有效方向。有效方向率是选择了有效方向的旋转占比；但即使方向有效，所选角度仍可能增大误差。对于有效方向，使 <math class="inline-equation"><mi>e</mi><mo>(</mo><msub><mi>R</mi><mi>t</mi></msub><mo>,</mo><mi>d</mi><mo>,</mo><mi>θ</mi><mo>)</mo></math> 取最小值的合法角度组成最佳角度集合 <math class="inline-equation"><msup><mi>Θ</mi><mo>★</mo></msup></math>。最佳合法角度率是选中集合中角度的比例。角度差是所选角度与最佳合法角度的差值；角度损失是所选角度额外造成的姿态误差。</p><p data-language="en">We also compare changes in IoU and pose error, and correlate rotation angles with both values before each action.</p><p data-language="zh">我们还比较 IoU 与姿态误差的变化，并分析每次动作前的旋转角度与这两项数值之间的相关性。</p></div>'''
    body = f'''<main class="page about-page"><section class="hero"><div class="eyebrow">{bilingual("方法 · 研究问题", "Method · Research Question")}</div><h1>{bilingual("将二维观察转化为精确的三维操作", "From 2D Observations to Precise 3D Action")}</h1><p>{bilingual("视觉语言模型能否将二维观察转化为支持精确操作的三维理解？RoTA-Bench 通过交互式三维到二维投影对齐评估这一能力。", "Can vision-language models turn 2D observations into 3D understanding that supports precise action? RoTA-Bench evaluates this ability through interactive 3D-to-2D projection alignment.")}</p></section><section class="section method-visuals"><figure class="paper-figure"><h3>{bilingual("RoTA-Bench 概览", "RoTA-Bench Overview")}</h3><img loading="lazy" src="/assets/rota-overview.png" alt="RoTA-Bench overview" data-alt-zh="RoTA-Bench 基准概览" data-alt-en="RoTA-Bench benchmark overview"><figcaption>{bilingual("论文原图：任务、交互观察与投影对齐。", "Original paper figure: tasks, interaction observations, and projection alignment.")}</figcaption></figure><figure class="paper-figure"><h3>{bilingual("自动化构建流程", "Automated Construction Pipeline")}</h3><img loading="lazy" src="/assets/rota-pipeline.png" alt="RoTA-Bench construction pipeline" data-alt-zh="RoTA-Bench 自动化构建流程" data-alt-en="RoTA-Bench automated construction pipeline"><figcaption>{bilingual("论文原图：任务生成、参考搜索、测试集构建和闭环评测。", "Original paper figure: task generation, reference search, test-set construction, and closed-loop evaluation.")}</figcaption></figure></section><section class="section"><h2>{bilingual("背景与动机", "Background and Motivation")}</h2><div class="source-copy">{source_intro}</div></section><section class="section"><h2>{bilingual("基准设计与方法", "Benchmark Design and Method")}</h2><h3>{bilingual("设计动机", "Design Rationale")}</h3><div class="source-copy">{source_motivation}</div><h3>{bilingual("任务定义", "Task Definition")}</h3><div class="source-copy">{source_task}</div><h3>{bilingual("数据集构建", "Dataset Construction")}</h3><div class="source-copy">{source_construction}</div><h3>{bilingual("评测指标", "Evaluation Metrics")}</h3><div class="source-copy">{source_metrics}</div></section>
<section class="section"><h2>{bilingual("方法：交互式投影对齐", "Method: Interactive Projection Alignment")}</h2><p class="section-intro">{bilingual("每个任务由刚性三维物体、初始姿态和标准目标姿态构成。每一步，环境提供目标投影、当前物体的深度阴影辅助视图和当前投影。求解者从六个有向旋转方向与四种角度步长中选择操作，环境更新三维状态并重新生成观察。", "Each task consists of a rigid 3D object, an initial pose, and a canonical target pose. At each step, the environment provides the target projection, a depth-shaded auxiliary view, and the current projection. The solver selects from six signed rotation directions and four step sizes; the environment updates the 3D state and regenerates the observations.")}</p><div class="grid"><article class="card"><h3>{bilingual("从图标构造物体", "From Icons to 3D Objects")}</h3><p>{bilingual("我们从二维矢量图标筛选形状，在球面包络内沿深度方向对称挤出。这样既限制任意旋转下的空间范围，也使标准正面视图保留原图标的细节。", "We curate 2D vector icons and symmetrically extrude them along the depth axis under a spherical envelope. This bounds the spatial profile under arbitrary rotations while preserving the original icon's fine-grained details in the canonical front view.")}</p></article><article class="card"><h3>{bilingual("保证任务可解", "Guaranteeing Solvability")}</h3><p>{bilingual("初始姿态由可逆的离散旋转序列生成；反向执行该序列即可回到目标姿态，因此每个任务在构造时即保证可解。", "Initial poses are generated by reversible sequences of discrete rotations. Reversing the sequence restores the target pose, guaranteeing that every task is solvable by construction.")}</p></article><article class="card"><h3>{bilingual("搜索参考与冻结测试集", "Search References and Frozen Test Split")}</h3><p>{bilingual("我们以姿态引导 beam search 和限制在 30° 操作的广度优先搜索计算并验证参考路径，并保留较短的已验证路径。按参考路径长度分层抽样冻结 100 个测试任务；674 个任务中的其余 574 个保留供训练与后续研究。参考路径不是全局最优性证明。", "We compute and verify reference paths with pose-guided beam search and breadth-first search restricted to 30° actions, retaining the shorter verified path. We freeze 100 test tasks through stratified sampling over reference path lengths; the remaining 574 of 674 tasks are reserved for training and future research. A Search reference is not a proof of global optimality.")}</p></article></div></section>
<section class="section"><h2>{bilingual("交互评测", "Interactive Evaluation")}</h2><p class="section-intro">{bilingual("排行榜页提供完整模型结果和可交互的性能分析；Paper 页保留论文摘要与精选图示。", "The Leaderboard presents model results and interactive performance analyses. The Paper page presents the paper's abstract and selected figures.")}</p><a class="button" href="/leaderboard">{bilingual("查看排行榜", "View leaderboard")}</a></section>
<section class="section"><h2>{bilingual("附录轨迹样例", "Appendix Trajectory Examples")}</h2><p class="section-intro">{bilingual("以下成功与未成功轨迹来自论文附录，展示 GPT-5.6-Sol 每一步收到的视觉观察和原始动作响应。", "The successful and unsuccessful trajectories below are from the paper appendix. They show the visual observations and original action responses received at each step by GPT-5.6-Sol.")}</p><div class="case-gallery"><figure><img loading="lazy" src="/assets/success-example-start.png" alt="Successful example, initial observations"><figcaption>{bilingual("成功轨迹 · single_00270 · 第 1–4 步", "Successful trajectory · single_00270 · steps 1–4")}</figcaption></figure><figure><img loading="lazy" src="/assets/success-example-final.png" alt="Successful example, final observation"><figcaption>{bilingual("成功轨迹 · 第 5–8 步及最终状态", "Successful trajectory · steps 5–8 and final state")}</figcaption></figure><figure><img loading="lazy" src="/assets/failure-example-start.png" alt="Unsuccessful example, initial observations"><figcaption>{bilingual("未成功轨迹 · single_00039 · 第 1–4 步", "Unsuccessful trajectory · single_00039 · steps 1–4")}</figcaption></figure><figure><img loading="lazy" src="/assets/failure-example-final.png" alt="Unsuccessful example, final observation"><figcaption>{bilingual("未成功轨迹 · 第 9–12 步及最终状态", "Unsuccessful trajectory · steps 9–12 and final state")}</figcaption></figure></div></section></main>'''
    body = body.replace('<section class="section"><h2>' + bilingual("附录轨迹样例", "Appendix Trajectory Examples"), render_method_appendix(bilingual) + '<section class="section"><h2>' + bilingual("附录轨迹样例", "Appendix Trajectory Examples"))
    return page("Method", body, "about")


@lru_cache(maxsize=1)
def load_task_catalog() -> list[dict]:
    split = json.loads(open(TEST_SPLIT_PATH, encoding="utf-8").read())
    wanted = set(split.get("sample_ids", []))
    catalog = []
    with open(TASKS_PATH, encoding="utf-8") as handle:
        for line in handle:
            sample_match = re.search(r'"sample_id"\s*:\s*"([^"]+)"', line)
            if not sample_match or sample_match.group(1) not in wanted:
                continue
            slug_match = re.search(r'"icon_slug"\s*:\s*"([^"]*)"', line)
            if sample_match:
                sample_id = sample_match.group(1)
                item = json.loads(line)
                catalog.append({"sample_id": sample_id, "category": "all", "icon_slug": slug_match.group(1) if slug_match else "task", "preview": f"/api/preview?task={sample_id}"})
    return sorted(catalog, key=lambda item: item["sample_id"])


@lru_cache(maxsize=1)
def load_human_paths() -> dict[str, list[dict]]:
    return {sid: item['human'] for sid, item in json.loads(Path(PUBLIC_PATHS).read_text(encoding='utf-8')).items()}


@lru_cache(maxsize=1)
def load_reference_paths() -> dict[str, list[dict]]:
    return {sid: item['reference'] for sid, item in json.loads(Path(PUBLIC_PATHS).read_text(encoding='utf-8')).items()}


def play_html() -> str:
    catalog = load_task_catalog()
    human_paths = load_human_paths()
    reference_paths = load_reference_paths()
    def solution_markup(item):
        human = human_paths.get(item["sample_id"], [])
        human_text = " · ".join(f'{action["action"]}({action["angle"]}°)' for action in human) or "暂无公开记录 / No public record"
        reference = reference_paths.get(item["sample_id"]) or []
        reference_text = " · ".join(f'{action["action"]}({action["angle"]}°)' for action in reference) or "暂无 / Not available"
        return f'<details class="task-solutions"><summary>{bilingual("查看答案路径", "View answer paths")}</summary><div class="solution-line"><strong>{bilingual("人类路径", "Human path")}</strong> · {len(human)} {bilingual("步", "steps")}<br><span class="solution-actions">{human_text}</span></div><div class="solution-line"><strong>{bilingual("Search 参考路径（非全局最优证明）", "Search reference (not a global-optimality proof)")}</strong> · {len(reference)} {bilingual("步", "steps")}<br><span class="solution-actions">{reference_text}</span></div><div class="solution-line">{bilingual("解法仅供演示；正式评测中不向参与者或模型提供。", "Paths are shown for demonstration only and are hidden during formal evaluation.")}</div></details>'
    cards = "".join(f'<div class="task-card-wrap"><button class="task-card" data-task="{x["sample_id"]}" data-icon="{x["icon_slug"]}"><span class="task-preview"><img loading="lazy" src="{x["preview"]}" alt="{x["sample_id"]} target preview"><span class="task-preview-scan"></span></span><strong>{x["sample_id"]}</strong><small>{x["icon_slug"]}</small></button>{solution_markup(x)}</div>' for x in catalog)
    body = f'''<main class="play-shell"><section class="play-stage"><div id="gameLoader" class="game-loader" role="status" aria-live="polite"><div class="loader-core"><span class="loader-orbit"></span><span class="loader-orbit orbit-two"></span><span class="loader-glyph">R</span></div><strong>{bilingual("正在载入任务", "LOADING TASK")}</strong><small id="loaderTask">RoTA-Bench · {catalog[0]["sample_id"]}</small><div class="loader-meter"><i></i></div></div><iframe id="demoFrame" class="demo-frame" src="/demo?task={catalog[0]["sample_id"]}" title="{bilingual("RoTA-Bench 交互式演示", "RoTA-Bench interactive demo")}"></iframe></section><section class="mission-board"><div class="eyebrow">{bilingual(f"RoTA-Bench · 测试集 · {len(catalog)} 个任务", f"RoTA-Bench · test split · {len(catalog)} tasks")}</div><h1>{bilingual("选择任务", "Select a task")}</h1><p>{bilingual("选择预览图以载入对应的测试任务。展开卡片可查看公开演示中的人类路径与参考路径；正式评测时这些答案不可见。", "Select a preview to load its test task. Expand a card to view the human and reference paths released for this demo; these answers are hidden during formal evaluation.")}</p><div class="task-scroll"><div class="pixel-grid">{cards}</div></div></section></main>'''
    return page("Play", body, "play") + '<script>const frame=document.getElementById("demoFrame"),loader=document.getElementById("gameLoader"),loaderTask=document.getElementById("loaderTask");function showLoader(task){loader.classList.remove("is-ready");loaderTask.textContent="RoTA-Bench · "+task;}function syncDemoLanguage(){frame.contentWindow?.postMessage({type:"rota-language",language:document.body.classList.contains("language-en")?"en":"zh"},location.origin);}frame.addEventListener("load",syncDemoLanguage);window.addEventListener("message",event=>{if(event.origin!==location.origin)return;if(event.data?.type==="rota-demo-ready"){if(event.data.ok){loader.classList.add("is-ready");}else{loaderTask.textContent=document.body.classList.contains("language-en")?"LOAD FAILED · SELECT A TASK TO RETRY":"载入失败 · 选择其他任务重试";}return;}if(event.data?.type!=="rota-language-request"||!["zh","en"].includes(event.data.language))return;localStorage.setItem("rota-language",event.data.language);document.body.classList.toggle("language-en",event.data.language==="en");document.documentElement.lang=event.data.language==="zh"?"zh-CN":"en";document.getElementById("language-toggle").textContent=event.data.language==="zh"?"EN":"中文";requestAnimationFrame(syncDemoLanguage);});document.querySelectorAll(".task-card").forEach(card=>card.addEventListener("click",()=>{if(card.classList.contains("active"))return;document.querySelectorAll(".task-card").forEach(x=>x.classList.remove("active"));card.classList.add("active");showLoader(card.dataset.task);frame.src="/demo?task="+card.dataset.task;}));const first=document.querySelector(".task-card");first?.classList.add("active");showLoader(first?.dataset.task||"");syncDemoLanguage();</script>'


def create_app() -> FastAPI:
    app = FastAPI(title="RoTA-Bench")

    @app.get("/", response_class=HTMLResponse)
    async def home() -> str:
        return home_html()

    @app.get("/play", response_class=HTMLResponse)
    async def play() -> str:
        return play_html()

    @app.get("/api/tasks")
    async def tasks_api() -> list[dict]:
        return load_task_catalog()

    @app.get("/api/leaderboard")
    async def leaderboard_api() -> list[dict]:
        return json.loads(open(os.path.join(ROOT, "assets", "leaderboard.json"), encoding="utf-8").read())

    @app.get("/leaderboard", response_class=HTMLResponse)
    async def leaderboard() -> str:
        return leaderboard_html()

    @app.get("/paper", response_class=HTMLResponse)
    async def paper() -> str:
        return paper_html()

    @app.get("/about", response_class=HTMLResponse)
    async def about() -> str:
        return about_html()

    @app.get("/assets/rotabench-paper.pdf")
    async def paper_file() -> Response:
        with open(PAPER_PATH, "rb") as handle:
            return Response(content=handle.read(), media_type="application/pdf", headers={"Content-Disposition": "inline; filename=rotabench-paper.pdf", "Cache-Control": "public, max-age=3600"})

    @app.get("/paper/download")
    async def paper_download() -> FileResponse:
        return FileResponse(PAPER_PATH, media_type="application/pdf", filename="RoTA-Bench.pdf", headers={"Cache-Control": "no-cache"})

    @app.get("/assets/{asset_name}")
    async def public_asset_file(asset_name: str) -> FileResponse:
        allowed = {
            "success-example-start.png": ("image/png", None),
            "success-example-final.png": ("image/png", None),
            "failure-example-start.png": ("image/png", None),
            "failure-example-final.png": ("image/png", None),
            "paper-data.json": ("application/json", None),
            "paper-interactive.js": ("text/javascript", None),
            "paper-main-charts.js": ("text/javascript", None),
            "cost-chart.js": ("text/javascript", None),
            "leaderboard-top10.json": ("application/json", None),
            "rota-overview.png": ("image/png", None),
            "method-human-interface.png": ("image/png", None),
            "method-prompt-01.png": ("image/png", None),
            "method-prompt-02.png": ("image/png", None),
            "method-prompt-03.png": ("image/png", None),
            "rota-pipeline.png": ("image/png", None),
        }
        if asset_name not in allowed:
            return Response(status_code=404)
        media_type = allowed[asset_name][0]
        return FileResponse(os.path.join(ROOT, "assets", asset_name), media_type=media_type, headers={"Cache-Control": "public, max-age=3600"})

    @app.api_route("/demo", methods=["GET"])
    @app.api_route("/api/preview", methods=["GET"])
    @app.api_route("/api/{path:path}", methods=["GET", "POST"])
    @app.api_route("/assets/{path:path}", methods=["GET"])
    async def proxy(request: Request, path: str = "") -> Response:
        upstream_path = "/" if request.url.path == "/demo" else request.url.path
        async with httpx.AsyncClient(timeout=120, trust_env=False) as client:
            upstream = await client.request(request.method, INTERNAL_ORIGIN + upstream_path, params=request.query_params, content=await request.body(), headers={"content-type": request.headers.get("content-type", ""), "cookie": request.headers.get("cookie", "")})
        return proxy_response(upstream)

    return app


def main() -> None:
    thread = threading.Thread(target=run_projection_server, daemon=True)
    thread.start()
    wait_for_projection_server()
    uvicorn.run(create_app(), host="0.0.0.0", port=int(os.environ.get("PORT", "7860")))


if __name__ == "__main__":
    main()
